<script lang="ts">
 import SocialLogo from './SocialLogo.svelte';
 import ProfileImageCropper from './ProfileImageCropper.svelte';
 import {onMount,onDestroy} from 'svelte';
 import {guardUnsaved} from './unsaved';
 import {request} from './api';
 import {Input} from '$lib/components/ui/input';
 import {Textarea} from '$lib/components/ui/textarea';
 import {Button} from '$lib/components/ui/button';
 import {LoaderCircle,Plus,Trash2,ExternalLink,ArrowUp,ArrowDown} from '@lucide/svelte';
 let {onSaved=()=>{}}:{onSaved?:(user:any)=>void}=$props();
 const socialPresets=[{label:'YouTube',url:'https://www.youtube.com/@'},{label:'Instagram',url:'https://www.instagram.com/'},{label:'TikTok',url:'https://www.tiktok.com/@'},{label:'LinkedIn',url:'https://www.linkedin.com/in/'},{label:'GitHub',url:'https://github.com/'},{label:'X',url:'https://x.com/'},{label:'Facebook',url:'https://www.facebook.com/'},{label:'Twitch',url:'https://www.twitch.tv/'},{label:'Discord',url:'https://discord.gg/'},{label:'Telegram',url:'https://t.me/'},{label:'Website',url:'https://'}];
 function moveSocial(index:number,direction:number){const target=index+direction;if(target<0||target>=profile.social_links.length)return;const links=[...profile.social_links];[links[index],links[target]]=[links[target],links[index]];profile.social_links=links;}
 function addSocial(preset:{label:string;url:string}){if(profile.social_links.length<8)profile.social_links=[...profile.social_links,{label:preset.label,url:preset.url}];}
 let imagePreviews=$state<Record<string,string>>({});
 let crop=$state<{source:string;kind:'avatar'|'banner'}|null>(null);
 onDestroy(()=>closeCrop());
 function closeCrop(){if(crop)URL.revokeObjectURL(crop.source);crop=null;}
 function uploadImage(event:Event,kind:'avatar'|'banner'){
  const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;error='';notice='';
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){error='Choose a JPG, PNG or WebP image smaller than 12 MB.';input.value='';return;}
  closeCrop();crop={source:URL.createObjectURL(file),kind};input.value='';
 }
 async function applyCrop(preview:string){if(!crop)return;const kind=crop.kind;busy=true;try{const result=await request('/profile/images',{kind,data:preview.split(',')[1]});profile[`${kind}_url`]=result.url;imagePreviews={...imagePreviews,[kind]:preview};notice='Image prepared. Save your profile to publish it.';closeCrop();}finally{busy=false;}}
 let savedProfile=$state('');
 guardUnsaved(()=>!!profile&&!!savedProfile&&JSON.stringify(profile)!==savedProfile,'Leave without saving profile changes?');
 let publicVideos=$state<any[]>([]);
 let profile=$state<any>(null),loading=$state(true),busy=$state(false),error=$state(''),notice=$state('');
 async function load(){loading=true;error='';try{const result=await request('/profile');profile={...result.channel,social_links:result.channel.social_links || []};savedProfile=JSON.stringify(profile);const channel=await request(`/channels/${encodeURIComponent(profile.handle)}`);publicVideos=channel.videos||[];}catch(e){error=(e as Error).message;}finally{loading=false;}}
 onMount(()=>{void load();});
 async function save(){busy=true;error='';notice='';try{const {name,bio,location,avatar_url,banner_url,website,social_links,featured_video_id}=profile;const result=await request('/profile',{name,bio,location,avatar_url,banner_url,website,social_links,featured_video_id},'PATCH');profile={...result.channel,social_links:result.channel.social_links || []};savedProfile=JSON.stringify(profile);onSaved(result.user);notice='Your public profile has been updated.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
{#if crop}<ProfileImageCropper source={crop.source} kind={crop.kind} onapply={applyCrop} oncancel={closeCrop}/>{/if}
<div class="page-heading"><h1>Edit public profile</h1><p>Your profile is shared by your viewing account and creator channel. Email and security settings stay private.</p></div>
{#if error}<div class="cloud-alert" role="alert">{error}{#if !profile}<Button variant="outline" onclick={load}>Retry</Button>{/if}</div>{/if}{#if notice}<p class="cloud-notice" role="status">{notice}</p>{/if}
{#if loading}<div class="cloud-loading" role="status"><LoaderCircle class="size-5 animate-spin"/>Loading profile…</div>{:else if profile}<form class="cloud-panel profile-editor" onsubmit={(event)=>{event.preventDefault();void save();}}><div class="section-heading"><h2>Public identity</h2><a href={`/channels/${profile.handle}`} class="inline-flex items-center gap-1 text-sm underline underline-offset-4">View profile<ExternalLink class="size-3.5"/></a></div><div class="profile-image-preview"><div class="banner-preview">{#if profile.banner_url}<img src={imagePreviews.banner||profile.banner_url} alt="Your channel banner preview" referrerpolicy="no-referrer"/>{:else}<span>Your channel banner</span>{/if}</div><div class="avatar-preview">{#if profile.avatar_url}<img src={imagePreviews.avatar||profile.avatar_url} alt="Your profile avatar preview" referrerpolicy="no-referrer"/>{:else}<span>{(profile.name||"V").slice(0,1).toUpperCase()}</span>{/if}</div></div><label for="profile-name">Display name</label><Input id="profile-name" bind:value={profile.name} required maxlength={100} autocomplete="name"/><label for="profile-bio">Bio</label><Textarea id="profile-bio" bind:value={profile.bio} rows={4} maxlength={2000}/><label for="profile-location">Location <span class="subtle">(optional)</span></label><Input id="profile-location" bind:value={profile.location} maxlength={120}/><div class="image-upload-actions"><label class="image-upload-button">Upload avatar<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={e=>uploadImage(e,'avatar')}/></label><label class="image-upload-button">Upload banner<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={e=>uploadImage(e,'banner')}/></label></div><p class="field-help">JPG, PNG or WebP, up to 12 MB. Zoom and position your square avatar or wide banner, then review the preview before saving.</p><details class="image-link-options"><summary>Use an image link instead</summary><div class="form-grid"><div><label for="profile-avatar">Avatar image URL</label><Input id="profile-avatar" type="url" bind:value={profile.avatar_url} placeholder="https://"/></div><div><label for="profile-banner">Banner image URL</label><Input id="profile-banner" type="url" bind:value={profile.banner_url} placeholder="https://"/></div></div><p class="field-help">Use HTTPS image links. SVG and data URLs are not accepted. Leave a URL empty to remove it.</p></details><label for="profile-website">Website</label><Input id="profile-website" type="url" pattern="https://.*" bind:value={profile.website} placeholder="https://"/><label for="profile-featured">Featured video</label><select id="profile-featured" class="profile-featured-select" bind:value={profile.featured_video_id}><option value="">No featured video</option>{#each publicVideos as video}<option value={video.id}>{video.title}{video.audience==='members'?' · Premium':''}</option>{/each}</select><p class="field-help">Feature a published public video at the top of your profile. Choose from up to 60 recent releases, including your current feature. Premium access rules still apply.</p><div class="section-heading profile-links-heading"><h2>Social links</h2><Button type="button" variant="outline" size="sm" disabled={profile.social_links.length>=8} onclick={()=>profile.social_links=[...profile.social_links,{label:'',url:''}]}><Plus class="size-4"/>Add link</Button></div><p class="field-help">Add a platform, then complete your profile URL. Up to eight public links.</p><div class="social-presets">{#each socialPresets as preset}<Button type="button" variant="outline" size="sm" disabled={busy||profile.social_links.length>=8||profile.social_links.some((link:any)=>link.label===preset.label)} onclick={()=>addSocial(preset)}><SocialLogo name={preset.label}/>{preset.label}</Button>{/each}</div>{#each profile.social_links as link,index}<div class="profile-link-row"><div><label for={`social-label-${index}`}>Label {index+1}</label><Input id={`social-label-${index}`} bind:value={link.label} required maxlength={40}/></div><div><label for={`social-url-${index}`}>HTTPS URL</label><Input id={`social-url-${index}`} type="url" pattern="https://.*" bind:value={link.url} required/></div><div class="profile-link-actions"><Button type="button" variant="ghost" size="icon-sm" disabled={index===0} aria-label={`Move social link ${index+1} up`} onclick={()=>moveSocial(index,-1)}><ArrowUp class="size-4"/></Button><Button type="button" variant="ghost" size="icon-sm" disabled={index===profile.social_links.length-1} aria-label={`Move social link ${index+1} down`} onclick={()=>moveSocial(index,1)}><ArrowDown class="size-4"/></Button><Button type="button" variant="ghost" size="icon" aria-label={`Remove social link ${index+1}`} onclick={()=>profile.social_links=profile.social_links.filter((_:unknown,i:number)=>i!==index)}><Trash2 class="size-4"/></Button></div></div>{/each}<div class="profile-save"><p class="field-help">Only information you enter here appears on your public profile.</p><Button type="submit" disabled={busy}>{#if busy}<LoaderCircle class="size-4 animate-spin"/>{/if}Save profile</Button></div></form>{/if}

<style>.profile-link-actions{display:flex;align-items:center;gap:2px}.image-link-options{margin:18px 0 24px}.image-link-options summary{font-size:13px;color:var(--muted-foreground);cursor:pointer}.image-link-options[open] summary{margin-bottom:16px}@media(max-width:600px){.profile-link-actions{grid-column:2;grid-row:1 / span 2;flex-direction:column}}.image-upload-actions{display:flex;gap:10px;flex-wrap:wrap}.image-upload-button{position:relative;overflow:hidden;display:inline-flex;align-items:center;min-height:36px;padding:8px 12px;border:1px solid var(--border);border-radius:var(--radius);font-size:13px;cursor:pointer}.image-upload-button:hover{background:var(--accent)}.image-upload-button:focus-within{outline:2px solid var(--ring);outline-offset:3px}.image-upload-button input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.profile-image-preview{position:relative;margin:10px 0 36px}.banner-preview{height:160px;background:var(--muted);border-radius:12px;overflow:hidden;display:grid;place-items:center;color:var(--muted-foreground);font-size:13px}.banner-preview img{width:100%;height:100%;object-fit:cover}.avatar-preview{width:76px;height:76px;border:4px solid var(--background);border-radius:50%;background:var(--muted);position:absolute;left:20px;bottom:-24px;overflow:hidden;display:grid;place-items:center;font-size:26px;font-weight:600}.avatar-preview img{width:100%;height:100%;object-fit:cover}.social-presets{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 20px}@media(max-width:600px){.banner-preview{height:112px}}.profile-featured-select{width:100%;min-height:36px;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);padding:6px 10px;font-size:13px}.profile-featured-select:focus-visible{outline:2px solid var(--ring);outline-offset:3px}</style>
